import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# 1) Element‑wise addition (provided in the example – kept for completeness)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


# ----------------------------------------------------------------------
# 2) Custom sum‑reduction kernel (sum over a given dimension)
# ----------------------------------------------------------------------
sum_reduction_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void sum_reduction_kernel(const float* input, const int dim_size, float* output, int total_elements) {
    // Each thread computes the sum of one element's slice along 'dim_size'.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float sum = 0.0f;
        for (int k = 0; k < dim_size; ++k) {
            // Assuming input is stored row‑major with shape (total_elements, dim_size).
            float val = input[idx * dim_size + k];
            sum += val;
        }
        output[idx] = sum;
    }
}

torch::Tensor sum_reduction_cuda(torch::Tensor a, int dim) {
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (a.numel() + block_size - 1) / block_size;

    // total_elements is the number of elements before the reduced dimension.
    sum_reduction_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), dim, out.data_ptr<float>(), a.numel());

    return out;
}
"""

sum_reduction_cpp_source = (
    "torch::Tensor sum_reduction_cuda(torch::Tensor a, int dim);"
)

sum_reduction = load_inline(
    name="sum_reduction_cuda",
    cpp_sources=sum_reduction_cpp_source,
    cuda_sources=sum_reduction_source,
    functions=['sum_reduction_cuda'],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


# ----------------------------------------------------------------------
# 3) Optimized model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Optimized version of `Model` that uses the custom CUDA kernels defined above.
    The forward pass calls `sum_reduction_cuda(x, self.dim)` which performs a sum reduction
    along the specified dimension and returns an output tensor with shape (..., 1, ...).
    """

    def __init__(self) -> None:
        super().__init__()
        # Default to reducing over dimension 1 as in the original Model.
        self.dim = 1

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.sum_reduction_cuda(x, self.dim)
